def _parse_parameters_and_qualifiers(self, paramMode: str) -> ASTParametersQualifiers:
    if paramMode == 'new':
        return None
    self.skip_ws()
    if not self.skip_string('('):
        if paramMode == 'function':
            self.fail('Expecting "(" in parameters-and-qualifiers.')
        else:
            return None
    args = []
    self.skip_ws()
    if not self.skip_string(')'):
        while 1:
            self.skip_ws()
            if self.skip_string('...'):
                args.append(ASTFunctionParameter(None, True))
                self.skip_ws()
                if not self.skip_string(')'):
                    self.fail('Expected ")" after "..." in '
                              'parameters-and-qualifiers.')
                break
            # note: it seems that function arguments can always be named,
            # even in function pointers and similar.
            arg = self._parse_type_with_init(outer=None, named='single')
            # TODO: parse default parameters # TODO: didn't we just do that?
            args.append(ASTFunctionParameter(arg))

            self.skip_ws()
            if self.skip_string(','):
                continue
            elif self.skip_string(')'):
                break
            else:
                self.fail(
                    'Expecting "," or ")" in parameters-and-qualifiers, '
                    'got "%s".' % self.current_char)

    # TODO: why did we have this bail-out?
    # does it hurt to parse the extra stuff?
    # it's needed for pointer to member functions
    if paramMode != 'function' and False:
        return ASTParametersQualifiers(
            args, None, None, None, None, None, None, None)

    self.skip_ws()
    const = self.skip_word_and_ws('const')
    volatile = self.skip_word_and_ws('volatile')
    if not const:  # the can be permuted
        const = self.skip_word_and_ws('const')

    refQual = None
    if self.skip_string('&&'):
        refQual = '&&'
    if not refQual and self.skip_string('&'):
        refQual = '&'

    exceptionSpec = None
    self.skip_ws()
    if self.skip_string('noexcept'):
        if self.skip_string_and_ws('('):
            expr = self._parse_constant_expression(False)
            self.skip_ws()
            if not self.skip_string(')'):
                self.fail("Expecting ')' to end 'noexcept'.")
            exceptionSpec = ASTNoexceptSpec(expr)
        else:
            exceptionSpec = ASTNoexceptSpec(None)

    self.skip_ws()
    if self.skip_string('->'):
        trailingReturn = self._parse_type(named=False)
    else:
        trailingReturn = None

    self.skip_ws()
    override = self.skip_word_and_ws('override')
    final = self.skip_word_and_ws('final')
    if not override:
        override = self.skip_word_and_ws(
            'override')  # they can be permuted

    self.skip_ws()
    initializer = None
    if self.skip_string('='):
        self.skip_ws()
        valid = ('0', 'delete', 'default')
        for w in valid:
            if self.skip_word_and_ws(w):
                initializer = w
                break
        if not initializer:
            self.fail(
                'Expected "%s" in initializer-specifier.'
                % '" or "'.join(valid))

    return ASTParametersQualifiers(
        args, volatile, const, refQual, exceptionSpec, trailingReturn,
        override, final, initializer)

def _parse_decl_specs_simple(self, outer: str, typed: bool) -> ASTDeclSpecsSimple:
    """Just parse the simple ones."""
    storage = None
    threadLocal = None
    inline = None
    virtual = None
    explicit = None
    constexpr = None
    volatile = None
    const = None
    friend = None
    attrs = []
    while 1:  # accept any permutation of a subset of some decl-specs
        self.skip_ws()
        if not storage:
            if outer in ('member', 'function'):
                if self.skip_word('static'):
                    storage = 'static'
                    continue
                if self.skip_word('extern'):
                    storage = 'extern'
                    continue
            if outer == 'member':
                if self.skip_word('mutable'):
                    storage = 'mutable'
                    continue
            if self.skip_word('register'):
                storage = 'register'
                continue
        if not threadLocal and outer == 'member':
            threadLocal = self.skip_word('thread_local')
            if threadLocal:
                continue

        if outer == 'function':
            # function-specifiers
            if not inline:
                inline = self.skip_word('inline')
                if inline:
                    continue
            if not friend:
                friend = self.skip_word('friend')
                if friend:
                    continue
            if not virtual:
                virtual = self.skip_word('virtual')
                if virtual:
                    continue
            if not explicit:
                explicit = self.skip_word('explicit')
                if explicit:
                    continue

        if not constexpr and outer in ('member', 'function'):
            constexpr = self.skip_word("constexpr")
            if constexpr:
                continue
        if not volatile and typed:
            volatile = self.skip_word('volatile')
            if volatile:
                continue
        if not const and typed:
            const = self.skip_word('const')
            if const:
                continue
        attr = self._parse_attribute()
        if attr:
            attrs.append(attr)
            continue
        break
    return ASTDeclSpecsSimple(storage, threadLocal, inline, virtual,
                              explicit, constexpr, volatile, const,
                              friend, attrs)

